assign_impl!(Scalar -= f64);
assign_impl!(Scalar *= Scalar);
assign_impl!(Scalar *= f64);
assign_impl!(Scalar /= Scalar);
assign_impl!(Scalar /= f64);
assign_impl!(Scalar %= Scalar);
assign_impl!(Scalar %= f64);

